import { CloudOff } from "lucide-react";
import { lazy, Suspense, useEffect, type ReactNode } from "react";
import {
  Link,
  Navigate,
  Route,
  Routes,
  useLocation,
} from "react-router-dom";
import { NotFoundPage } from "./components/not-found/NotFoundPage";
import { useAccountStore } from "./lib/auth";
import { cn } from "./lib/cn";
import { useInkFlow } from "./store/inkflow";
import { ThemeController } from "./theme/ThemeController";
import "./clean-app.css";

const KnowledgeLibraryPage = lazy(() =>
  import("./components/knowledge/KnowledgeLibraryPage").then((module) => ({
    default: module.KnowledgeLibraryPage,
  })),
);
const CorpusPage = lazy(() =>
  import("./components/corpus/CorpusPage").then((module) => ({
    default: module.CorpusPage,
  })),
);
const VocabularyPage = lazy(() =>
  import("./components/vocabulary/VocabularyPage").then((module) => ({
    default: module.VocabularyPage,
  })),
);

function LazyRoute({ children }: { children: ReactNode }) {
  return <Suspense fallback={null}>{children}</Suspense>;
}

function OfflineBanner() {
  const { apiOnline, deepseekConfigured, bootstrapped } = useInkFlow();
  if (!bootstrapped || apiOnline) return null;
  return (
    <div className="offline-banner">
      <CloudOff size={15} />
      <span>
        Local mode is active. Configure the API to enable DeepSeek and
        persistent sync.
      </span>
      <small>{deepseekConfigured ? "API unavailable" : "No API key"}</small>
    </div>
  );
}

function Toast() {
  const { toast } = useInkFlow();
  return (
    <div className={cn("toast", toast && "is-visible")} role="status">
      {toast?.message}
    </div>
  );
}

function CleanNav() {
  const { pathname } = useLocation();
  const items = [
    { to: "/", label: "知识库" },
    { to: "/corpus", label: "语料库" },
    { to: "/vocabulary", label: "单词本" },
  ];
  return (
    <header className="clean-nav">
      <Link className="clean-nav__brand" to="/">
        <img src="/leafia-mark.svg" alt="" />
        <span>
          <strong>Leafia</strong>
          <small>English learning workspace</small>
        </span>
      </Link>
      <nav aria-label="主要导航">
        {items.map((item) => (
          <Link
            key={item.to}
            className={cn(
              pathname === item.to && "is-active",
              item.to !== "/" &&
                pathname.startsWith(`${item.to}/`) &&
                "is-active",
            )}
            to={item.to}
          >
            {item.label}
          </Link>
        ))}
      </nav>
    </header>
  );
}

export function AppClean() {
  const bootstrap = useInkFlow((state) => state.bootstrap);
  const bootstrapAccount = useAccountStore((state) => state.bootstrap);

  useEffect(() => {
    void bootstrap();
    void bootstrapAccount();
  }, [bootstrap, bootstrapAccount]);

  return (
    <div className="inkflow-app clean-app">
      <ThemeController />
      <CleanNav />
      <OfflineBanner />
      <div className="motion-route-stage" data-motion-root>
        <Routes>
          <Route
            path="/"
            element={
              <LazyRoute>
                <KnowledgeLibraryPage />
              </LazyRoute>
            }
          />
          <Route
            path="/shelf"
            element={<Navigate to="/library" replace />}
          />
          <Route
            path="/study"
            element={<Navigate to="/library" replace />}
          />
          <Route
            path="/reading"
            element={<Navigate to="/library" replace />}
          />
          <Route
            path="/reading/:chapterId"
            element={<Navigate to="/library" replace />}
          />
          <Route
            path="/inkverse/:bookId"
            element={<Navigate to="/library" replace />}
          />
          <Route
            path="/library"
            element={
              <LazyRoute>
                <KnowledgeLibraryPage />
              </LazyRoute>
            }
          />
          <Route
            path="/library/:categoryId"
            element={
              <LazyRoute>
                <KnowledgeLibraryPage />
              </LazyRoute>
            }
          />
          <Route
            path="/write/:noteId"
            element={<Navigate to="/library" replace />}
          />
          <Route
            path="/write/:noteId/:pageId"
            element={<Navigate to="/library" replace />}
          />
          <Route
            path="/book/:bookId"
            element={<Navigate to="/library" replace />}
          />
          <Route
            path="/corpus"
            element={
              <LazyRoute>
                <CorpusPage />
              </LazyRoute>
            }
          />
          <Route
            path="/vocabulary"
            element={
              <LazyRoute>
                <VocabularyPage />
              </LazyRoute>
            }
          />
          <Route path="*" element={<NotFoundPage />} />
        </Routes>
      </div>
      <Toast />
    </div>
  );
}
